#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_MAX 0x400
static char main_out[OUT_MAX];

static void to_camel(const char *src) {
    size_t out_len = 0;
    int capitalize = 0;
    for (size_t i = 0; src[i] != '\0' && out_len < OUT_MAX - 1; ++i) {
        char c = src[i];
        if (c == '_') { capitalize = 1; continue; }
        if (capitalize && c >= 'a' && c <= 'z') c = (char)toupper((unsigned char)c);
        capitalize = 0;
        main_out[out_len++] = c;
    }
    main_out[out_len] = '\0';
}

static void to_snake(const char *src) {
    size_t out_len = 0;
    for (size_t i = 0; src[i] != '\0' && out_len < OUT_MAX - 1; ++i) {
        char c = src[i];
        if (c >= 'A' && c <= 'Z') {
            if (out_len < OUT_MAX - 2) {
                main_out[out_len++] = '_';
                c = (char)tolower((unsigned char)c);
                main_out[out_len++] = c;
                continue;
            }
        }
        main_out[out_len++] = c;
    }
    main_out[out_len] = '\0';
}

int main(int argc, char *argv[]) {
    if (argc < 3) { puts("USAGE"); return 0; }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
    } else {
        puts("INVALID_MODE");
        return 0;
    }
    puts(main_out);
    return 0;
}
